import crypto from 'node:crypto';
import fs from 'node:fs';
/** Synthetic contract fixtures only. Optional sourceFile binds generated bytes
 * for execution tests. This is not an independent detection/source receipt. */
export function syntheticMeasuredContext(context:any,sourceFile?:string):any {
 const sourceSha256=sourceFile?crypto.createHash('sha256').update(fs.readFileSync(sourceFile)).digest('hex'):'a'.repeat(64);
 const sourceStoragePath='synthetic-test/source.mp4',sourceAssetId='synthetic-test-clip';
 const track=context.track;
 return {...context,sourceSha256,sourceStoragePath,sourceAssetId,decodedSource:{width:track.source_width,height:track.source_height},track:{...track,status:'ready',clip_id:sourceAssetId,analysis_version:1,analyzed_aspect_ratio:context.aspectRatio,metadata:{...track.metadata,analyzed_source_sha256:sourceSha256,analyzed_source_path:sourceStoragePath,analyzed_source_start:context.clipStartSec,analyzed_source_end:context.clipStartSec+track.metadata.clip_duration}}};
}
